# ! [feature (slicing_syntax)] # ! [feature (associated_types)] # ! [feature (macro_rules)] use std :: iter ; use std :: os ; use std :: io :: File ; # [allow (unused)] pub fn parse_summary < R : Reader > (_ : R , _ : & Path) { let path_from_root = Path :: new ("") ; Path :: new (iter :: repeat ("../") . take (path_from_root . components () . count () - 1) . collect :: < String > ()) ; } fn main () { let cwd = os :: getcwd () . unwrap () ; let src = cwd . clone () ; let summary = File :: open (& src . join ("SUMMARY.md")) ; let _ = parse_summary (summary , & src) ; }